import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  const geometry = new PlaneGeometry(1.6, 1); // 512x320 aspect ratio
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: false,
  });

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Border accent plane (slightly larger)
  const borderGeo = new PlaneGeometry(1.64, 1.04); // +0.02 margin on each side
  const borderMat = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    transparent: true,
    opacity: 0,
    side: 2, // both sides
    depthWrite: false,
  });
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.renderOrder = 1;
  borderMesh.position.z = 0.001; // slightly in front
  group.add(borderMesh);

  // Load texture
  let texture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --- Interactions ---
  const hoverTimeline = gsap.timeline({ paused: true });
  const pressTimeline = gsap.timeline({ paused: true });

  function onPointerOver() {
    gsap.to(mesh.position, { y: 0.15, duration: 0.3, ease: 'power2.out' });
    gsap.to(borderMat, { opacity: 1, duration: 0.3, ease: 'power2.out' });
  }

  function onPointerOut() {
    gsap.to(mesh.position, { y: 0, duration: 0.3, ease: 'power2.out' });
    gsap.to(borderMat, { opacity: 0, duration: 0.3, ease: 'power2.out' });
  }

  function onPointerDown() {
    gsap.to(mesh.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out' });
  }

  function onPointerUp() {
    gsap.to(mesh.scale, { x: 1, y: 1, duration: 0.12, ease: 'back.out' });
    ctx.emit('hub-journal.select');
  }

  userData.handlers = {
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    pointerdown: onPointerDown,
    pointerup: onPointerUp,
  };

  // --- Cinematic Primitives ---
  let primCleanup = null;
  const parallaxCfg = config.cinematicPrimitives?.find(p => p.name === 'parallax-scroll');
  if (parallaxCfg) {
    const result = ctx.primitives['parallax-scroll'](group, { intensity: 0.25 });
    primCleanup = result.cleanup;
  }

  // --- Cleanup ---
  userData.cleanup = () => {
    // Kill all GSAP tweens on this node's objects
    gsap.killTweensOf(mesh);
    gsap.killTweensOf(borderMat);
    gsap.killTweensOf(mesh.position);
    gsap.killTweensOf(mesh.scale);
    gsap.killTweensOf(borderMesh);

    // Dispose geometry
    geometry.dispose();
    borderGeo.dispose();

    // Dispose material
    material.dispose();
    borderMat.dispose();

    // Dispose texture
    if (texture) texture.dispose();

    // Primitive cleanup
    if (primCleanup) primCleanup();
  };

  // Apply scene position from config (already handled by adapter, but set as fallback)
  group.position.set(config.scenePosition?.x ?? 2.5, config.scenePosition?.y ?? 0.7, config.scenePosition?.z ?? 0);
  group.rotation.set(config.scenePosition?.rotation?.x ?? 0, config.scenePosition?.rotation?.y ?? 0, config.scenePosition?.rotation?.z ?? 0);
  group.scale.set(config.scenePosition?.scale?.x ?? 1, config.scenePosition?.scale?.y ?? 1, config.scenePosition?.scale?.z ?? 1);

  return group;
}
